<!-- 文件作用：打手工作台，管理服务并领取真实公开需求。 -->
<template><AppShell active="worker" title="把热爱，变成实力" subtitle="不必挂靠俱乐部，也能凭本事接单。">
  <view v-if="!state.user" class="mt"><EmptyState title="你的主场，等你上线" detail="登录后可以发布服务、领取需求，也可以选择加入俱乐部。" icon="work"><button class="btn" @click="go('/pages/login/index?next=' + encodeURIComponent('/pages/worker/index'))">登录，开始接单</button></EmptyState></view>
  <template v-else><view class="worker-summary"><view><text class="eyebrow">YOUR ARENA</text><view class="worker-greeting">{{ state.user.nickname }}<text>，今天也全力以赴</text></view><view class="worker-state"><text class="status-dot"/>{{ state.user.provider_enabled ? '接单身份已开启' : '完善资料，开启接单身份' }}</view></view><view class="worker-emblem"><Icon name="work" :size="38"/></view></view>
    <view class="stats-grid"><view><text>{{ stats.working_count || 0 }}</text><view>进行中的服务</view></view><view><text>{{ stats.completed_count || 0 }}</text><view>已完成订单</view></view><view><text><text class="currency">¥</text>{{ money(stats.earnings_cents) }}</text><view>已完成收入</view></view></view>
    <view v-if="!state.user.provider_enabled" class="notice row between"><text>每个人都能成为打手。先完善你的介绍，再开启接单。</text><button class="btn btn-small" @click="go('/pages/me/index')">去完善</button></view>
    <view class="worker-actions"><button class="btn" :disabled="!state.user.provider_enabled" @click="go('/pages/publish/index')"><Icon name="plus" :size="17" color="#05170e"/> 发布服务</button><button class="btn btn-secondary" @click="go('/pages/clubs/index')"><Icon name="club" :size="17"/> 发现俱乐部</button></view>
    <view class="tabs"><view class="tab" :class="{active:tab === 'jobs'}" @click="changeTab('jobs')">接单大厅</view><view class="tab" :class="{active:tab === 'services'}" @click="changeTab('services')">我的服务 <text v-if="mine.length">{{ mine.length }}</text></view><view class="tab" @click="go('/pages/orders/index?role=provider')">进行中订单</view></view>
    <GamePicker v-if="tab === 'jobs'"/>
    <view v-if="error" class="error-box mt stack"><text>{{ error }}</text><button class="btn btn-small btn-secondary" @click="load">重新加载</button></view>
    <view v-else-if="loading" class="loading-line">正在寻找新的机会…</view>
    <template v-else-if="tab === 'jobs'"><view class="section-row"><text class="section-title">等待你的队友</text><text class="muted">{{ jobs.length }} 个需求</text></view><view v-if="jobs.length" class="stack"><view v-for="job in jobs" :key="job.id" class="job-card"><view class="row between"><text class="pill pill-accent">{{ game.short_name }} · 公开需求</text><text class="hint">{{ time(job.created_at) }}</text></view><view class="job-title">{{ job.title }}</view><view v-if="job.requirements" class="job-description">{{ job.requirements }}</view><view class="job-bottom"><view><text class="job-price">¥{{ money(job.amount_cents) }}</text><text class="hint"> / 预算</text></view><button class="btn btn-small" :disabled="!state.user.provider_enabled || claiming === job.id" @click="claim(job)">{{ claiming === job.id ? '领取中…' : '立即接单' }}</button></view></view></view><EmptyState v-else title="现在还没有待接需求" detail="试试切换其他游戏，或者发布自己的服务，让玩家找到你。" icon="game"/></template>
    <template v-else><view class="section-row"><text class="section-title">我的服务</text><text class="muted">审核后展示给玩家</text></view><view v-if="mine.length" class="stack"><view v-for="service in mine" :key="service.id" class="my-service"><view class="row service-main" @click="go('/pages/service/index?id=' + service.id)"><image :src="assetUrl(service.cover_url)" mode="aspectFill"/><view class="my-service-info"><view>{{ service.title }}</view><text class="pill">{{ statusLabel(service.status) }}</text><text class="my-price">¥{{ money(service.price_cents) }}</text></view></view><view class="service-controls"><button class="btn btn-small btn-secondary" @click="go('/pages/publish/index?id=' + service.id)"><Icon name="edit" :size="12"/>编辑服务</button><button v-if="service.status === 'active'" class="btn btn-small btn-secondary" :disabled="pausing === service.id" @click="pause(service)">暂停接单</button><text v-else class="hint">{{ service.status === 'pending' ? '等待平台审核' : '编辑后重新提交审核' }}</text></view></view></view><EmptyState v-else title="让你的实力被看见" detail="选择游戏、定好服务内容和价格，制作一张专属封面。" icon="photo"><button class="btn btn-small" :disabled="!state.user.provider_enabled" @click="go('/pages/publish/index')">发布第一项服务</button></EmptyState></template>
    <view class="notice mt">承诺可交付的服务，不接外挂、账号租售或违规任务。每个订单都有独立聊天室，关键约定请留在订单中。</view>
  </template>
</AppShell></template>
<script setup>
import { ref, watch } from 'vue'
import { onShow } from '@dcloudio/uni-app'
import AppShell from '../../components/AppShell.vue'
import Icon from '../../components/Icon.vue'
import GamePicker from '../../components/GamePicker.vue'
import EmptyState from '../../components/EmptyState.vue'
import { state, game, init } from '../../lib/store'
import { api } from '../../lib/api'
import { money, time, statusLabel, go, notify, assetUrl } from '../../lib/format'
const claimClubs = ref([])
const tab = ref('jobs'), jobs = ref([]), mine = ref([]), stats = ref({}), error = ref(''), loading = ref(false), claiming = ref(''), pausing = ref('')
let version = 0
/** 读取公开需求、个人服务和真实订单统计。 */
async function load() { const current = ++version; loading.value = true; error.value = ''; try { await init(); if (!state.user) return; const [orders, services, summary, clubs] = await Promise.all([api('/jobs?game_id=' + encodeURIComponent(state.gameId)), api('/services?mine=1'), api('/me/stats'), api('/clubs?mine=1')]); if (current === version) { jobs.value = orders || []; mine.value = services || []; stats.value = summary || {}; claimClubs.value = (clubs || []).filter(club => club.status === 'active' && ['owner','active'].includes(club.membership_status)) } } catch (err) { if (current === version) error.value = err.message } finally { if (current === version) loading.value = false } }
/** 切换工作台内容并重新读取服务状态。 */
function changeTab(value) { tab.value = value; load() }
/** 原子领取公开需求，并进入订单沟通。 */
async function claim(job) { if (claiming.value) return; claiming.value = job.id; try { const clubId = await chooseClaimClub(job.game_id); if (clubId === null) return; const order = await api('/orders/' + job.id + '/actions', 'POST', { action: 'claim', note: '', club_id: clubId }); go('/pages/order/index?id=' + order.id) } catch (err) { notify(err); load() } finally { claiming.value = '' } }
/** 接公开需求时明确选择有效挂靠，取消不产生订单变更。 */
function chooseClaimClub(gameId) { const clubs = claimClubs.value.filter(club => (club.game_ids || []).includes(gameId)); return clubs.length ? showClaimClubPage(clubs, 0) : Promise.resolve('') }
/** 每页最多六个操作，兼容微信动作菜单限制并允许选择任意数量的挂靠。 */
function showClaimClubPage(clubs, page) { const options = [{ name: '独立接单（不挂靠）', id: '' }, ...clubs.slice(page * 3, page * 3 + 3)]; if (page > 0) options.push({ name: '上一页俱乐部', page: page - 1 }); if ((page + 1) * 3 < clubs.length) options.push({ name: '下一页俱乐部', page: page + 1 }); return new Promise(resolve => uni.showActionSheet({ itemList: options.map(option => option.name), success: result => { const option = options[result.tapIndex]; resolve(option.page === undefined ? option.id : showClaimClubPage(clubs, option.page)) }, fail: () => resolve(null) })) }
/** 暂停本人已上架服务，刷新列表避免继续展示旧状态。 */
async function pause(service) { if (pausing.value) return; pausing.value = service.id; try { await api('/services/' + service.id + '/pause', 'POST', {}); notify('服务已暂停'); await load() } catch (err) { notify(err) } finally { pausing.value = '' } }
watch(() => state.gameId, load)
onShow(load)
</script>
<style scoped>.worker-summary{background:var(--surface);border:1px solid rgba(255,255,255,.09);border-radius:16px;padding:22px 18px;display:flex;align-items:center;justify-content:space-between}.worker-greeting{font-size:19px;font-weight:750;margin-top:9px}.worker-greeting>text{display:block;font-size:12px;font-weight:400;color:#a0b2a6;margin-top:5px}.worker-state{display:flex;align-items:center;gap:6px;font-size:10px;color:var(--accent);margin-top:18px}.worker-emblem{color:var(--accent);background:rgba(255,255,255,.03);border:1px solid rgba(255,255,255,.05);width:72px;height:72px;border-radius:50%;display:flex;align-items:center;justify-content:center}.stats-grid{display:grid;grid-template-columns:1fr 1fr 1fr;margin:20px 0}.stats-grid>view{text-align:center;padding:7px 0;border-right:1px solid rgba(255,255,255,.08)}.stats-grid>view:last-child{border:0}.stats-grid>view>text{font-weight:750;font-size:23px}.stats-grid>view>view{font-size:9px;color:#8a9c90;margin-top:4px}.currency{font-size:12px}.worker-actions{display:flex;gap:10px;margin:23px 0}.worker-actions>.btn{flex:1;font-size:12px;padding:12px 8px}.job-card{padding:17px;border:1px solid rgba(255,255,255,.08);border-radius:13px;background:var(--surface)}.job-title{font-size:17px;font-weight:650;margin-top:16px}.job-description{font-size:12px;color:#8fa096;margin-top:8px;line-height:1.7;white-space:pre-wrap;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.job-bottom{display:flex;align-items:center;justify-content:space-between;margin-top:18px;padding-top:14px;border-top:1px solid rgba(255,255,255,.07)}.job-price{font-size:24px;color:var(--accent);font-weight:750}.my-service{padding:14px;background:var(--surface);border:1px solid rgba(255,255,255,.08);border-radius:13px}.service-main{align-items:flex-start}.service-main image{width:82px;height:67px;flex-shrink:0;border-radius:7px}.my-service-info{flex:1;min-width:0}.my-service-info>view{font-size:14px;margin-bottom:7px;overflow:hidden;white-space:nowrap;text-overflow:ellipsis}.my-price{font-size:17px;color:var(--accent);margin-left:12px}.service-controls{display:flex;align-items:center;justify-content:flex-end;gap:9px;border-top:1px solid rgba(255,255,255,.07);padding-top:12px;margin-top:13px}</style>
